// Уровень B2 — частицы, pluskvamperfektum и причастия, косвенная речь, словообразование, стиль, диалекты и нюнорск.

U({
  id: 'b2-1', lvl: 'B2', t: 'Частицы jo, vel, da, nå: тон разговора', en: 'Modalpartikler',
  goals: ['понимать оттенки *jo, vel, da, nå, altså, visst*', 'звучать естественно, а не «как учебник»', 'не обидеть собеседника неправильным *da*'],
  th: `<p>Маленькие безударные слова, которые ничего не значат по словарю, но меняют <b>тон</b>. Без них норвежская речь звучит сухо, как перевод. С ними — живо.</p>
  <div class="tbl"><table><thead><tr><th>Частица</th><th>Оттенок</th><th>Пример</th><th>Как по-русски</th></tr></thead><tbody>
  <tr><td><b>jo</b></td><td>«ты же знаешь», общеизвестное</td><td><i>Det regner <b>jo</b> alltid i Bergen.</i></td><td>«ведь, же»</td></tr>
  <tr><td><b>vel</b></td><td>предположение, ждём согласия</td><td><i>Du kommer <b>vel</b>?</i></td><td>«ты ведь придёшь?», «наверное»</td></tr>
  <tr><td><b>da</b></td><td>нетерпение, усиление, смягчение просьбы</td><td><i>Kom <b>da</b>! · Så fint <b>da</b>!</i></td><td>«ну же!», «ну как мило!»</td></tr>
  <tr><td><b>nå</b></td><td>«ну, вообще-то», лёгкое возражение</td><td><i>Det er <b>nå</b> ikke så farlig.</i></td><td>«ну, не так уж»</td></tr>
  <tr><td><b>altså</b></td><td>«то есть», «вот правда», вывод или эмоция</td><td><i>Du er <b>altså</b> ferdig? · Herlig, <b>altså</b>!</i></td><td>«значит», «ну просто»</td></tr>
  <tr><td><b>visst</b></td><td>«как говорят», «оказывается»</td><td><i>Han er <b>visst</b> syk.</i></td><td>«вроде бы, говорят»</td></tr>
  <tr><td><b>bare</b></td><td>смягчение приглашения</td><td><i>Bare sett deg!</i></td><td>«да садись же»</td></tr></tbody></table></div>
  <h4>Где стоят</h4>
  <p>Как <i>ikke</i>: после глагола в главном предложении (<i>Han er <b>jo</b> her</i>), перед глаголом в придаточном (<i>…fordi han <b>jo</b> er her</i>). <i>da</i> в просьбах и восклицаниях — в конце.</p>
  <h4>Осторожно с da</h4>
  <p><i>Hei da!</i> — «ну, пока!» (тепло). Но <i>Hva er det da?</i> с раздражённой интонацией — «ну и что это ещё такое?». Слушайте интонацию. А «Ja da» и «Nei da» — «да-да, конечно», «да нет, что вы».</p>`,
  simple: 'jo — «ведь, сам знаешь», vel — «наверное, ведь да?», da — «ну же!», nå — «ну, вообще-то», visst — «говорят». Стоят там же, где ikke.',
  exm: [['Det regner jo alltid i Bergen.', 'В Бергене же всегда дождь.'], ['Du kommer vel i morgen?', 'Ты ведь придёшь завтра?'], ['Kom igjen da!', 'Ну давай же!'], ['Han er visst flyttet til Oslo.', 'Говорят, он переехал в Осло.']],
  conf: [['*jo* (частица) / *jo* (да)', '<i>Jo!</i> отдельно — «да» на отрицательный вопрос. <i>jo</i> внутри фразы — «ведь».', '«Det er jo søndag» значит…|ведь сегодня воскресенье|да, воскресенье|разве воскресенье? # jo внутри фразы — «ведь».'],
    ['*vel* (частица) / *vel* (хорошо)', '<i>Du er vel trøtt?</i> — «ты, наверное, устал?» <i>Velkommen, vel bekomme</i> — тут «хорошо» (старое значение).', '«Du har vel spist?» — это…|ты ведь уже поел?|ты хорошо поел|поешь хорошо # vel — ожидаем «да».']],
  words: [['jo', 'ведь, же', 'Du vet jo det.'], ['vel', 'наверное, ведь (да?)', 'Det går vel bra?'], ['da', 'ну же, ну', 'Kom da!'], ['visst', 'вроде бы, говорят', 'Butikken er visst stengt.'], ['altså', 'то есть, ну просто', 'Herlig, altså!'], ['egentlig', 'вообще-то, на самом деле', 'Egentlig vil jeg hjem.'], ['faktisk', 'на самом деле, фактически', 'Det var faktisk gøy.'], ['liksom', 'типа, как бы', 'Han var liksom trøtt.'], ['ja da', 'да-да, конечно', 'Ja da, jeg kommer!'], ['nei da', 'да нет, что вы', 'Nei da, det var ikke noe.']],
  ex: [
    { t: 'choice', h: 'Какая частица подходит по смыслу?', q: ['Ты ждёшь согласия: «Du blir ___ med på festen?»|vel|jo|visst # Ожидание «да» — vel.', 'Общеизвестный факт: «Det er ___ kaldt i januar.»|jo|vel|da # «ведь» — jo.', 'Нетерпение: «Skynd deg ___!»|da|vel|visst # «ну же!» — da.', 'Слух: «Hun har ___ fått ny jobb.»|visst|jo|da # «говорят» — visst.', 'Мягкое возражение: «Det er ___ ikke så farlig.»|nå|vel|visst # nå — «ну, вообще-то».', 'Эмоция: «For en utsikt, ___!»|altså|vel|visst # altså — «ну просто!».'] },
    { t: 'order', hint: 'Частица стоит там же, где стояло бы ikke.', q: ['Det regner jo alltid i Bergen.', 'Du kommer vel i morgen?', 'Han er visst flyttet til Oslo.', 'Det var faktisk ganske gøy.', 'Hun sa at hun jo ikke hadde tid.'] },
    { t: 'gap', h: 'Вставьте частицу.', q: ['Ты не голоден? — ___ ! (да, конечно голоден)|Jo', 'Det går ___ bra? (наверное, да?)|vel', 'Kom igjen ___! (ну же)|da', 'Du vet ___ at jeg elsker vafler. (ведь)|jo', 'Takk for hjelpen! — Nei ___, det var ikke noe.|da'] },
    { t: 'fix', q: ['Det jo regner.|Det regner jo. # Частица — после глагола.', 'Du vel kommer?|Du kommer vel? # vel — после глагола.', 'Han sier at han er jo trøtt.|Han sier at han jo er trøtt. # В придаточном — перед глаголом.'] },
    { t: 'tr', q: ['В Бергене же всегда дождь.|Det regner jo alltid i Bergen.', 'Ты ведь придёшь?|Du kommer vel?', 'Говорят, магазин закрыт.|Butikken er visst stengt.', 'Да нет, ничего страшного.|Nei da, det er ikke så farlig.|Nei da, det gjør ikke noe.'] },
  ],
  read: {
    title: 'En samtale på trikken', intro: 'Найдите все частицы и подумайте, что каждая добавляет.',
    txt: ['— Du, er ikke det Alina? Hun kunstneren fra Riga? — Jo, det er visst henne. Hun har jo vært i avisa! — Har hun? Det visste jeg ikke.', '— Ja da. Hun har tegnet hele Norge, liksom. Fra Lofoten til Oslo. Og hun reiser med en lundefugl og ei måke. — En lundefugl? Du tuller vel? — Nei, altså! Se selv — der sitter han, på skulderen hennes.', '— Herregud. Det er da det søteste jeg har sett. Skal vi spørre om en autograf? — Nei, la henne nå være i fred, da.'],
    gl: { 'trikken': 'трамвай', 'avisa': 'газета', 'tegnet': 'нарисовала', 'tuller': 'шутишь', 'se selv': 'смотри сам', 'skulderen': 'плечо', 'herregud': 'боже мой', 'i fred': 'в покое' },
    q: [{ t: 'tf', q: ['Alina har vært i avisa.|T # «Hun har jo vært i avisa!»', 'Den andre personen visste det fra før.|F # «Det visste jeg ikke.»', 'Lundefuglen sitter på skulderen til Alina.|T', 'De spør om en autograf.|F # «La henne nå være i fred.»'] },
      { t: 'choice', q: ['Hva betyr «Du tuller vel?»|Ты ведь шутишь?|Ты устал?|Ты идёшь?', 'Hva betyr «la henne være i fred»?|оставь её в покое|пригласи её|сфотографируй её'] }],
  },
  series: [{ show: 'uttrykk', who: 'норвежское выражение', q: 'Ja vel.', mean: 'Зависит от интонации: «ну ладно», «понятно», а иногда — «ну-ну» (с сомнением).', fun: 'Иностранцы годами учатся слышать разницу между довольным <i>ja vel!</i> и скептическим <i>ja… vel</i>. Норвежцы различают сразу.', use: 'Vi møtes klokka åtte? — Ja vel, det passer.', qz: 'Скептическое «ja… vel» после вашего рассказа значит…|«ну-ну, сомневаюсь»|«отлично!»|«не понял» # Интонация решает.' },
    { show: 'kultur', who: 'типично норвежское', q: 'Koselig', mean: 'Норвежская «уютность»: свечи, плед, какао, тихий вечер с друзьями. Как датское <i>hygge</i>, только норвежское.', fun: 'Норвежцы говорят <i>koselig</i> о чём угодно: о доме, ужине, человеке и даже о разговоре. <i>Takk for sist, det var så koselig!</i> — «Спасибо за прошлую встречу, было так уютно!»', use: 'Det var så koselig å se deg igjen!', qz: 'Как ответить на «Takk for sist!»?|Takk i like måte, det var så koselig!|Hva sist?|Ja, det var sist. # «Takk for sist» — «спасибо за прошлую встречу».' }],
  write: { h: 'Напишите живой диалог двух друзей (10–12 реплик), где обсуждается новость. Используйте минимум 5 разных частиц.', min: 80, use: ['jo', 'vel', 'da', 'visst', 'altså'],
    plan: ['A сообщает новость (visst).', 'B удивляется, сомневается (vel?).', 'A уверяет (jo, altså).', 'B реагирует эмоцией (da!).', 'Договариваются о чём-то.'],
    model: '— Har du hørt? Kafeen på hjørnet er visst stengt.\n— Nei? Du tuller vel?\n— Nei, altså! Det sto jo på Facebook.\n— Men hvor skal vi drikke kaffe da?\n— Det finnes jo andre kafeer.\n— Ja vel, men ingen er like koselige.\n— Kom igjen da! Vi finner en ny.\n— Ja da, ja da. Men du betaler.' },
  vid: [['Learn Norwegian Naturally', 'Norwegian modal particles jo vel da'], ['NorwegianClass101', 'sound natural in Norwegian'], ['NRK', 'Norwegian conversation natural speed']],
  fact: 'В корпусе разговорного норвежского частица <i>da</i> — одно из 30 самых частых слов. Её почти никогда нет в учебниках, а без неё невозможно говорить «по-норвежски».',
  src: [['Wikibooks — Norwegian', 'https://en.wikibooks.org/wiki/Norwegian'], ['Naob — jo, vel, da', 'https://naob.no/'], ['Språkrådet', 'https://www.sprakradet.no/']],
});
